llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C41"],
      "claim": "Verapamil, the highest-transfer analogue, has absolute oral bioavailability of 52.3% in cirrhotic patients, demonstrating that a dimethoxyphenyl tertiary-amine scaffold can achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Praziquantel, with a related amide/lactam and aromatic system, shows 27.2% absolute oral bioavailability in patients with hepatic cirrhosis, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Noscapine, a dimethoxyphenyl isoquinoline alkaloid with a tertiary amine, has absolute oral bioavailability of 30% in humans, supporting high F for the query's similar fused aromatic/amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Sulpiride, a methoxybenzamide with a basic amine, has absolute oral bioavailability of 27-35% in humans, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Encainide, a dimethoxybenzamide with a basic piperidine, has oral bioavailability of 32 ± 7% in normal subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Valbenazine, which shares the dimethoxyphenyl tetrahydroisoquinoline motif and a basic amine, has absolute oral bioavailability of approximately 49% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Colchicine, a polymethoxyphenyl amide, has mean absolute oral bioavailability of 55% in elderly subjects, above the threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer analogues sharing dimethoxyphenyl, amide/lactam, and basic amine features show absolute oral bioavailability of 23-55%, all above the 20% threshold. The only low-F record is S-verapamil under rifampin co-treatment, a condition not applicable to the query. Therefore predict high.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the query molecule.",
    "The only low-F record (S-verapamil with rifampin, 0.7%) is under enzyme induction and not applicable to the query's uninduced condition.",
    "Physicochemical prior is mixed/unclear; low neutral fraction may affect absorption but is overridden by consistent analogue data.",
    "Potential first-pass metabolism and transporter effects for the query are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

